contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    // take an amount to deposit so the caller can have positive credit
    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (depositAmount)); require(depositAmount <= 1000000000000000000000000000000);
        require(address(this).balance >= depositAmount);
        // ensure this contract has credit in c for the caller (this test contract)
        c.deposit{value: depositAmount}(); if (__ESBMC_reverted()) return;
        bool reverted; c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }
        // On the original contract, after depositing >0, withdrawAll should NOT revert.
        assert(reverted == false);
    }
    receive() external payable {}
}

